// statix CLI reimplementation
// Reverse-engineered from observed behavior.

use std::env;
use std::process::ExitCode;

mod explain;
mod help;
mod parse;

fn main() -> ExitCode {
    let argv: Vec<String> = env::args().collect();
    let prog = program_name(&argv);
    let args: Vec<String> = argv.into_iter().skip(1).collect();

    match parse::run(&prog, &args) {
        Ok(exit) => ExitCode::from(exit),
        Err(code) => ExitCode::from(code),
    }
}

fn program_name(argv: &[String]) -> String {
    let zero = argv.first().map(|s| s.as_str()).unwrap_or("executable");
    let base = std::path::Path::new(zero)
        .file_name()
        .and_then(|s| s.to_str())
        .unwrap_or(zero);
    base.to_string()
}
RUST_EOF
echo OK

