// Manual CLI argument parser, reproducing the original clap-based behavior.

use crate::{explain, help};

/// Top-level entry point.
/// Returns Ok(exit_code) where exit_code is the process exit status.
pub fn run(prog: &str, args: &[String]) -> Result<u8, u8> {
    // No args: print the root help to stderr and exit 2.
    if args.is_empty() {
        eprint!("{}", help::root_text(prog));
        return Ok(2);
    }

    // Help / version must work in the top-level position.
    match args[0].as_str() {
        "-h" | "--help" => {
            print!("{}", help::root_text(prog));
            return Ok(0);
        }
        "-V" | "--version" => {
            print!("{}", help::version_text());
            return Ok(0);
        }
        _ => {}
    }

    // Anything starting with '-' at the top level is an unknown option.
    if args[0].starts_with('-') {
        top_unknown_arg(prog, &args[0]);
        return Ok(2);
    }

    let sub = args[0].as_str();
    let rest = &args[1..];
    match sub {
        "help" => cmd_help(prog, rest),
        "check" => cmd_check(prog, rest),
        "fix" => cmd_fix(prog, rest),
        "single" => cmd_single(prog, rest),
        "list" => cmd_list(prog, rest),
        "dump" => cmd_dump(prog, rest),
        "explain" => cmd_explain(prog, rest),
        other => {
            top_unknown_arg(prog, other);
            Ok(2)
        }
    }
}

fn top_unknown_arg(prog: &str, arg: &str) {
    eprintln!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context",
        arg
    );
    eprintln!();
    if arg.starts_with('-') && !arg.starts_with("--") && arg.len() > 1 {
        eprintln!("\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`", arg, arg);
        eprintln!();
    }
    eprintln!("USAGE:");
    eprintln!("    {} <SUBCOMMAND>", prog);
    eprintln!();
    eprintln!("For more information try --help");
}

fn cmd_help(prog: &str, args: &[String]) -> Result<u8, u8> {
    if args.is_empty() {
        print!("{}", help::root_text(prog));
        return Ok(0);
    }
    // `help --help` and unknown help targets print an error
    match args[0].as_str() {
        "check" => {
            print!("{}", help::check_text(prog));
            Ok(0)
        }
        "fix" => {
            print!("{}", help::fix_text(prog));
            Ok(0)
        }
        "single" => {
            print!("{}", help::single_text(prog));
            Ok(0)
        }
        "explain" => {
            print!("{}", help::explain_text(prog));
            Ok(0)
        }
        "list" => {
            print!("{}", help::list_text(prog));
            Ok(0)
        }
        "dump" => {
            print!("{}", help::dump_text(prog));
            Ok(0)
        }
        "help" => {
            // `help help`: clap emits the root help (no help for help).
            print!("{}", help::root_text(prog));
            Ok(0)
        }
        other => {
            eprintln!("error:  The subcommand '{}' wasn't recognized", other);
            eprintln!();
            eprintln!("USAGE:");
            eprintln!("    {} <subcommands>", prog);
            eprintln!();
            eprintln!("For more information try --help");
            Ok(2)
        }
    }
}

fn cmd_list(prog: &str, args: &[String]) -> Result<u8, u8> {
    if let Some(code) = check_noopt_help(args, &|| help::list_text(prog)) {
        return Ok(code);
    }
    if !args.is_empty() {
        list_dump_unexpected(prog, "list", &args[0]);
        return Ok(2);
    }
    print!("{}", explain::lint_list());
    Ok(0)
}

fn cmd_dump(prog: &str, args: &[String]) -> Result<u8, u8> {
    if let Some(code) = check_noopt_help(args, &|| help::dump_text(prog)) {
        return Ok(code);
    }
    if !args.is_empty() {
        list_dump_unexpected(prog, "dump", &args[0]);
        return Ok(2);
    }
    print!("{}", explain::dump_config());
    Ok(0)
}

fn list_dump_unexpected(prog: &str, sub: &str, arg: &str) {
    eprintln!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context",
        arg
    );
    eprintln!();
    if arg.starts_with('-') && !arg.starts_with("--") && arg.len() > 1 {
        eprintln!(
            "\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`",
            arg, arg
        );
        eprintln!();
    }
    eprintln!("USAGE:");
    eprintln!("    {} {}", prog, sub);
    eprintln!();
    eprintln!("For more information try --help");
}

fn check_noopt_help(args: &[String], text: &dyn Fn() -> String) -> Option<u8> {
    for a in args {
        if a == "-h" || a == "--help" {
            print!("{}", text());
            return Some(0);
        }
    }
    None
}

fn cmd_explain(prog: &str, args: &[String]) -> Result<u8, u8> {
    // Parse position of TARGET; honor --help/-h before and after TARGET.
    let mut target: Option<String> = None;
    let mut iter = args.iter();
    while let Some(a) = iter.next() {
        match a.as_str() {
            "-h" | "--help" => {
                print!("{}", help::explain_text(prog));
                return Ok(0);
            }
            "--" => {
                if let Some(next) = iter.next() {
                    if target.is_none() {
                        target = Some(next.clone());
                    } else {
                        explain_too_many(prog, next);
                        return Ok(2);
                    }
                }
            }
            other if other.starts_with('-') && other != "-" => {
                explain_unknown_arg(prog, other);
                return Ok(2);
            }
            other => {
                if target.is_none() {
                    target = Some(other.to_string());
                } else {
                    explain_too_many(prog, other);
                    return Ok(2);
                }
            }
        }
    }

    let target = match target {
        Some(t) => t,
        None => {
            eprintln!("error: The following required arguments were not provided:");
            eprintln!("    <TARGET>");
            eprintln!();
            eprintln!("USAGE:");
            eprintln!("    {} explain <TARGET>", prog);
            eprintln!();
            eprintln!("For more information try --help");
            return Ok(2);
        }
    };

    // Value parser: if the input starts with 'W' or 'w', strip it and
    // parse the remainder as u32. On failure, emit the clap-style
    // "Invalid value" error and exit 2. Otherwise, store the parsed
    // u32. If the input doesn't start with W/w, do not validate here —
    // the subcommand will reject it further down.
    enum Parsed {
        Code(u32),
        NoPrefix,
    }
    let parsed = if let Some(rest) = target.strip_prefix(|c| c == 'W' || c == 'w') {
        match rest.parse::<u32>() {
            Ok(v) => Parsed::Code(v),
            Err(_) => {
                eprintln!(
                    "error: Invalid value for '<TARGET>': unable to parse `{}` as warning code",
                    target
                );
                eprintln!();
                eprintln!("For more information try --help");
                return Ok(2);
            }
        }
    } else {
        Parsed::NoPrefix
    };

    match parsed {
        Parsed::NoPrefix => {
            // No W prefix — behave the way statix does: print "syntax error".
            println!("syntax error");
            Ok(0)
        }
        Parsed::Code(0) => {
            // Code 0 is treated as an internal "syntax error" marker.
            println!("syntax error");
            Ok(0)
        }
        Parsed::Code(n) => match explain::lookup(n) {
            Some(text) => {
                print!("{}", text);
                Ok(0)
            }
            None => {
                eprintln!("explain error: lint with code `{}` not found", n);
                Ok(0)
            }
        },
    }
}

fn explain_too_many(prog: &str, arg: &str) {
    eprintln!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context",
        arg
    );
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("    {} explain <TARGET>", prog);
    eprintln!();
    eprintln!("For more information try --help");
}

fn explain_unknown_arg(prog: &str, arg: &str) {
    eprintln!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context",
        arg
    );
    eprintln!();
    if arg.starts_with('-') && !arg.starts_with("--") && arg.len() > 1 {
        eprintln!(
            "\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`",
            arg, arg
        );
        eprintln!();
    }
    eprintln!("USAGE:");
    eprintln!("    {} explain <TARGET>", prog);
    eprintln!();
    eprintln!("For more information try --help");
}

// ---------- check / fix / single ----------

#[derive(Default)]
struct CheckOpts {
    target: Option<String>,
    config: String,
    ignore: Vec<String>,
    format: String,
    stdin: bool,
    unrestricted: bool,
    format_set: bool,
}

fn parse_check_like(
    prog: &str,
    sub: &str,
    args: &[String],
    allow_format: bool,
    allow_ignore: bool,
    allow_position: bool,
    allow_dry_run: bool,
    help_text: &dyn Fn() -> String,
) -> Result<Option<(Option<String>, CheckOpts, bool, Option<String>)>, u8> {
    // (target, opts, dry_run, position)
    let mut opts = CheckOpts {
        config: ".".to_string(),
        format: "stderr".to_string(),
        ..Default::default()
    };
    let mut dry_run = false;
    let mut position: Option<String> = None;
    let mut after_dd = false;

    let mut i = 0;
