        }
        match a.as_str() {
            "-h" | "--help" => {
                print!("{}", help_text());
                return Err(0);
            }
            "--" => {
                after_dd = true;
            }
            "-s" | "--stdin" => {
                opts.stdin = true;
            }
            "-u" | "--unrestricted" => {
                if !allow_ignore {
                    // single doesn't have -u
                    unexpected_arg(prog, sub, a, allow_position);
                    return Err(2);
                }
                opts.unrestricted = true;
            }
            "-d" | "--dry-run" => {
                if !allow_dry_run {
                    unexpected_arg(prog, sub, a, allow_position);
                    return Err(2);
                }
                dry_run = true;
            }
            "-c" | "--config" => {
                i += 1;
                if let Some(v) = args.get(i) {
                    opts.config = v.clone();
                } else {
                    missing_value(prog, sub, a, allow_position);
                    return Err(2);
                }
            }
            "-o" | "--format" => {
                if !allow_format {
                    unexpected_arg(prog, sub, a, allow_position);
                    return Err(2);
                }
                i += 1;
                if let Some(v) = args.get(i) {
                    if v == "json" {
                        eprintln!(
                            "error: Invalid value for '--format <FORMAT>': statix was not compiled with the `json` feature flag"
                        );
                        eprintln!();
                        eprintln!("For more information try --help");
                        return Err(2);
                    }
                    if v != "stderr" && v != "errfmt" {
