/// Top-level entry point.
/// Returns Ok(exit_code) where exit_code is the process exit status.
pub fn run(prog: &str, args: &[String]) -> Result<u8, u8> {
    // No args: print the root help to stderr and exit 2.
    if args.is_empty() {
        eprint!("{}", help::root_text(prog));
        return Ok(2);
    }

    // Help / version must work in the top-level position.
    match args[0].as_str() {
