fn parse_check_like(
    prog: &str,
    sub: &str,
    args: &[String],
    allow_format: bool,
    allow_ignore: bool,
    allow_position: bool,
    allow_dry_run: bool,
    help_text: &dyn Fn() -> String,
) -> Result<Option<(Option<String>, CheckOpts, bool, Option<String>)>, u8> {
    // (target, opts, dry_run, position)
    let mut opts = CheckOpts {
        config: ".".to_string(),
        format: "stderr".to_string(),
        ..Default::default()
    };
    let mut dry_run = false;
    let mut position: Option<String> = None;
    let mut after_dd = false;

    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if after_dd {
            if opts.target.is_none() {
                opts.target = Some(a.clone());
            } else {
                unexpected_arg(prog, sub, a, allow_position);
                return Err(2);
            }
            i += 1;
            continue;
        }
        match a.as_str() {
            "-h" | "--help" => {
                print!("{}", help_text());
                return Err(0);
            }
            "--" => {
                after_dd = true;
            }
            "-s" | "--stdin" => {
                opts.stdin = true;
            }
            "-u" | "--unrestricted" => {
                if !allow_ignore {
                    // single doesn't have -u
                    unexpected_arg(prog, sub, a, allow_position);
                    return Err(2);
                }
                opts.unrestricted = true;
            }
            "-d" | "--dry-run" => {
                if !allow_dry_run {
                    unexpected_arg(prog, sub, a, allow_position);
                    return Err(2);
                }
                dry_run = true;
            }
            "-c" | "--config" => {
                i += 1;
                if let Some(v) = args.get(i) {
                    opts.config = v.clone();
                } else {
                    missing_value(prog, sub, a, allow_position);
                    return Err(2);
                }
            }
            "-o" | "--format" => {
                if !allow_format {
                    unexpected_arg(prog, sub, a, allow_position);
                    return Err(2);
                }
                i += 1;
                if let Some(v) = args.get(i) {
                    if v == "json" {
                        eprintln!(
                            "error: Invalid value for '--format <FORMAT>': statix was not compiled with the `json` feature flag"
                        );
                        eprintln!();
                        eprintln!("For more information try --help");
                        return Err(2);
                    }
                    if v != "stderr" && v != "errfmt" {
                        eprintln!(
                            "error: \"{}\" isn't a valid value for '--format <FORMAT>'",
                            v
                        );
                        eprintln!("\t[possible values: stderr, errfmt]");
                        eprintln!();
                        eprintln!("For more information try --help");
                        return Err(2);
                    }
                    opts.format = v.clone();
                    opts.format_set = true;
                } else {
                    missing_value(prog, sub, a, allow_position);
                    return Err(2);
                }
            }
            "-i" | "--ignore" => {
                if !allow_ignore {
                    unexpected_arg(prog, sub, a, allow_position);
                    return Err(2);
                }
                i += 1;
                if let Some(v) = args.get(i) {
                    opts.ignore.push(v.clone());
                } else {
                    missing_value(prog, sub, a, allow_position);
                    return Err(2);
                }
            }
            "-p" | "--position" => {
                if !allow_position {
                    unexpected_arg(prog, sub, a, allow_position);
                    return Err(2);
                }
                i += 1;
                if let Some(v) = args.get(i) {
                    position = Some(v.clone());
                } else {
                    missing_value(prog, sub, a, allow_position);
                    return Err(2);
                }
            }
            other if other.starts_with('-') && other != "-" => {
                unexpected_arg(prog, sub, other, allow_position);
                return Err(2);
            }
            other => {
                if opts.target.is_none() {
                    opts.target = Some(other.to_string());
                } else {
                    unexpected_arg(prog, sub, other, allow_position);
                    return Err(2);
                }
            }
        }
        i += 1;
    }

    // Validate required args for single
    if allow_position {
        if position.is_none() {
            missing_position(prog, opts.target.is_some());
            return Err(2);
        }
        if opts.target.is_none() {
            missing_position_and_target(prog);
            return Err(2);
        }
    }

    Ok(Some((opts.target.clone(), opts, dry_run, position)))
}

