fn cmd_explain(prog: &str, args: &[String]) -> Result<u8, u8> {
    // Parse position of TARGET; honor --help/-h before and after TARGET.
    let mut target: Option<String> = None;
    let mut iter = args.iter();
    while let Some(a) = iter.next() {
        match a.as_str() {
            "-h" | "--help" => {
                print!("{}", help::explain_text(prog));
                return Ok(0);
            }
            "--" => {
                if let Some(next) = iter.next() {
                    if target.is_none() {
                        target = Some(next.clone());
                    } else {
                        explain_too_many(prog, next);
                        return Ok(2);
                    }
                }
            }
            other if other.starts_with('-') && other != "-" => {
                explain_unknown_arg(prog, other);
                return Ok(2);
            }
            other => {
                if target.is_none() {
                    target = Some(other.to_string());
                } else {
                    explain_too_many(prog, other);
                    return Ok(2);
                }
            }
        }
    }

    let target = match target {
        Some(t) => t,
        None => {
            eprintln!("error: The following required arguments were not provided:");
            eprintln!("    <TARGET>");
            eprintln!();
            eprintln!("USAGE:");
            eprintln!("    {} explain <TARGET>", prog);
            eprintln!();
            eprintln!("For more information try --help");
            return Ok(2);
        }
    };

    // Value parser: if the input starts with 'W' or 'w', strip it and
    // parse the remainder as u32. On failure, emit the clap-style
    // "Invalid value" error and exit 2. Otherwise, store the parsed
    // u32. If the input doesn't start with W/w, do not validate here —
    // the subcommand will reject it further down.
    enum Parsed {
        Code(u32),
        NoPrefix,
    }
    let parsed = if let Some(rest) = target.strip_prefix(|c| c == 'W' || c == 'w') {
        match rest.parse::<u32>() {
            Ok(v) => Parsed::Code(v),
            Err(_) => {
                eprintln!(
                    "error: Invalid value for '<TARGET>': unable to parse `{}` as warning code",
                    target
                );
                eprintln!();
                eprintln!("For more information try --help");
                return Ok(2);
            }
        }
    } else {
        Parsed::NoPrefix
    };

    match parsed {
        Parsed::NoPrefix => {
            // No W prefix — behave the way statix does: print "syntax error".
            println!("syntax error");
            Ok(0)
        }
        Parsed::Code(0) => {
            // Code 0 is treated as an internal "syntax error" marker.
            println!("syntax error");
            Ok(0)
        }
        Parsed::Code(n) => match explain::lookup(n) {
            Some(text) => {
                print!("{}", text);
                Ok(0)
            }
            None => {
                eprintln!("explain error: lint with code `{}` not found", n);
                Ok(0)
            }
        },
    }
}

