fn cmd_check(prog: &str, args: &[String]) -> Result<u8, u8> {
    let parsed = match parse_check_like(
        prog,
        "check",
        args,
        /*allow_format*/ true,
        /*allow_ignore*/ true,
        /*allow_position*/ false,
        /*allow_dry_run*/ false,
        &|| help::check_text(prog),
    ) {
        Ok(Some(p)) => p,
        Ok(None) => return Ok(0),
        Err(c) => return Ok(c),
    };
    let (target, opts, _dry, _pos) = parsed;
    let target = target.unwrap_or_else(|| ".".to_string());
    run_check(&target, &opts)
}

fn cmd_fix(prog: &str, args: &[String]) -> Result<u8, u8> {
    let parsed = match parse_check_like(
        prog,
        "fix",
        args,
        /*allow_format*/ false,
        /*allow_ignore*/ true,
        /*allow_position*/ false,
        /*allow_dry_run*/ true,
        &|| help::fix_text(prog),
    ) {
