        Ok(None) => return Ok(0),
        Err(c) => return Ok(c),
    };
    let (target, opts, _dry, _pos) = parsed;
    let target = target.unwrap_or_else(|| ".".to_string());
    run_noop_fs(&target, &opts, false)
}

fn cmd_single(prog: &str, args: &[String]) -> Result<u8, u8> {
    let parsed = match parse_check_like(
        prog,
        "single",
        args,
        /*allow_format*/ false,
        /*allow_ignore*/ false,
        /*allow_position*/ true,
        /*allow_dry_run*/ true,
        &|| help::single_text(prog),
    ) {
        Ok(Some(p)) => p,
        Ok(None) => return Ok(0),
        Err(c) => return Ok(c),
    };
    let (target, opts, _dry, _pos) = parsed;
    let target = target.unwrap_or_else(|| ".".to_string());
    run_noop_fs(&target, &opts, true)
}

fn run_check(target: &str, opts: &CheckOpts) -> Result<u8, u8> {
    if opts.stdin {
        // No linting implemented; stream nothing.
        return Ok(0);
    }
    // Config-error on missing path.
    match std::fs::metadata(target) {
        Ok(_) => Ok(0),
        Err(_) => {
            println!("config error: path error: file not found: {}", target);
            Ok(0)
        }
    }
}

fn run_noop_fs(target: &str, opts: &CheckOpts, is_single: bool) -> Result<u8, u8> {
    if opts.stdin {
        // Stream mode: echo the input through unchanged.
        use std::io::Read;
        let mut buf = String::new();
        let _ = std::io::stdin().read_to_string(&mut buf);
        print!("{}", buf);
        return Ok(0);
    }
    match std::fs::metadata(target) {
        Ok(_) => {
            if is_single {
                println!("single fix error: nothing to fix");
            }
            Ok(0)
        }
        Err(e) => {
            if is_single {
                let msg = e.to_string();
                println!("config error: path error: {} (os error 2)", msg_kind(&msg));
            } else {
                println!("config error: path error: file not found: {}", target);
            }
            Ok(0)
        }
    }
}

