/// Expand clustered short flags and short-flag+value pairs in the clap v3 style.
/// For known "value" short flags (-c, -o, -i, -p), if they appear inside a cluster,
/// the remainder becomes the value (e.g. "-cfoo" becomes "-c foo").
fn expand_short_clusters(args: &[String]) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    let mut end = false;
    for a in args {
        if end {
            out.push(a.clone());
            continue;
        }
        if a == "--" {
            end = true;
