            continue;
        }
        if a.starts_with("--") || !a.starts_with('-') || a.len() < 3 {
            out.push(a.clone());
            continue;
        }
        let rest: Vec<char> = a[1..].chars().collect();
        let mut i = 0;
        let mut pushed_any = false;
        while i < rest.len() {
            let c = rest[i];
            match c {
