                    out.push(format!("-{}", c));
                    pushed_any = true;
                    if i + 1 < rest.len() {
                        let v: String = rest[i + 1..].iter().collect();
                        out.push(v);
                    }
                    i = rest.len();
                }
                _ => {
                    // Unknown short flag - leave cluster intact for error reporting
                    if !pushed_any {
                        out.push(a.clone());
                        pushed_any = true;
                    } else {
                        let remaining: String = rest[i..].iter().collect();
                        out.push(format!("-{}", remaining));
                    }
                    i = rest.len();
                }
            }
        }
    }
    out
}
